//! The M5a control-plane protobuf (generated by prost from
//! `proto/control.proto`) plus small ergonomic constructors.
//!
//! Control plane only this milestone — data-plane messages (commit-push,
//! object-fetch, shared-push, ...) are defined in their own later slices.

// prost-generated code; don't hold it to our hand-written lint bar.
#[allow(clippy::all, clippy::pedantic, clippy::nursery)]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/softfig.net.control.v1.rs"));
}

pub use generated::{
    frame, Frame, HelloPayload, Ping, Pong, RelayConnect, RelayData, StateAnnounce,
};

impl Frame {
    /// A `Ping` control frame.
    pub fn ping(nonce: u64) -> Self {
        Self {
            kind: Some(frame::Kind::Ping(Ping { nonce })),
        }
    }

    /// A `Pong` control frame echoing `nonce`.
    pub fn pong(nonce: u64) -> Self {
        Self {
            kind: Some(frame::Kind::Pong(Pong { nonce })),
        }
    }

    /// A `StateAnnounce` frame: register reachability with the relay.
    pub fn state_announce(device_id: Vec<u8>, paired: bool) -> Self {
        Self {
            kind: Some(frame::Kind::StateAnnounce(StateAnnounce {
                device_id,
                paired,
            })),
        }
    }

    /// A `RelayConnect` frame: ask the relay to bridge to `target_device_id`.
    pub fn relay_connect(target_device_id: Vec<u8>) -> Self {
        Self {
            kind: Some(frame::Kind::RelayConnect(RelayConnect { target_device_id })),
        }
    }

    /// A `RelayData` frame carrying an opaque chunk of inner end-to-end
    /// ciphertext for the relay to forward.
    pub fn relay_data(payload: Vec<u8>) -> Self {
        Self {
            kind: Some(frame::Kind::RelayData(RelayData { payload })),
        }
    }
}

impl HelloPayload {
    /// Build the in-handshake identity payload at the current protocol version.
    /// `device_id` is the device's Ed25519 identity public key. The
    /// `static_attestation` (field 4) starts empty; the pairing layer fills it
    /// with the Ed25519 signature over the X25519 static (see
    /// [`crate::pairing::LocalDevice`]).
    pub fn new(device_id: Vec<u8>, device_name: impl Into<String>) -> Self {
        Self {
            protocol_version: crate::PROTOCOL_VERSION,
            device_id,
            device_name: device_name.into(),
            static_attestation: Vec::new(),
        }
    }
}
